<?php
/**
 * Known-good QR matrices, for comparing this plugin's encoder against.
 *
 * Generated once from the `qrcode` npm package — a reference implementation, not a
 * dependency: nothing here ships, and the plugin encodes its own codes with no
 * library at all. Each entry is a version 1, level M, single alphanumeric segment,
 * which is exactly what a ticket code is.
 *
 * The reference is cleverer than this plugin by default: given a code ending in
 * twelve digits it splits the string into an alphanumeric segment and a denser
 * numeric one, producing a different — equally valid — symbol. The vectors below
 * pin it to a single alphanumeric segment so that the two are answering the same
 * question. Comparing against the optimised form would have failed for one code in
 * five and told us nothing about correctness.
 *
 * @package QuickEventsManager
 */

return array(
	'QEVT-ABC123DEF456' => array(
		'version' => 1,
		'size'    => 21,
		'modules' => '',
	),
	'QEVT-000000000000' => array(
		'version' => 1,
		'size'    => 21,
		'modules' => '',
	),
	'QEVT-ZZZZZZZZZZZZ' => array(
		'version' => 1,
		'size'    => 21,
		'modules' => '',
	),
	'QEVT-1A2B3C4D5E6F' => array(
		'version' => 1,
		'size'    => 21,
		'modules' => '',
	),
	'QEVT-A1B2C3D4E5F6' => array(
		'version' => 1,
		'size'    => 21,
		'modules' => '',
	),
);
